import re

from django.core import validators
from django.utils.deconstruct import deconstructible
from django.utils.translation import gettext_lazy as _


@deconstructible
class ASCIIUsernameValidator(validators.RegexValidator):
    regex = r"^[\w.@+-]+\Z"
    message = _(
        "Digite um nome de usuário válido. Este valor pode conter apenas letras minúsculas (a-z) "
        "e maiúsculas (A-Z) sem acento, números e os caracteres @/./+/-/_."
    )
    flags = re.ASCII


@deconstructible
class UnicodeUsernameValidator(validators.RegexValidator):
    regex = r"^[\w.@+-]+\Z"
    message = _(
        "Insira um nome de usuário válido. Este valor pode conter apenas letras, "
        "números e os caracteres @/./+/-/_."
    )
    flags = 0
